'use strict';
// Generated from seven Genesis draft JSON files. All entries pending human review.
(()=>{
const entries=[{"ref":"Genesis 1:4","explanation":"God distinguishes light from darkness and calls the light good; creation is ordered by divine judgment rather than chance.","context":"The separation follows the first command for light and begins the pattern of distinctions in the creation week.","crossReferences":["2 Corinthians 4:6","1 John 1:5"],"application":"Believers should welcome God's light and reject works of darkness.","reviewStatus":"pending"},{"ref":"Genesis 1:5","explanation":"God names day and night, establishing the first evening-and-morning sequence in the narrative.","context":"Naming signals divine authority; the verse closes the first day of the creation account.","crossReferences":["Psalm 74:16","John 11:9"],"application":"Receive each day as entrusted time to serve God faithfully.","reviewStatus":"pending"},{"ref":"Genesis 1:6","explanation":"God commands an expanse amid the waters to separate waters above from waters below.","context":"The second day's work describes the ordering of the created world using the observational language of Genesis.","crossReferences":["Psalm 19:1","Psalm 148:4"],"application":"Creation invites reverence for the Creator rather than speculation beyond the text.","reviewStatus":"pending"},{"ref":"Genesis 1:7","explanation":"God carries out his command by making the firmament and dividing the waters; the account stresses obedience of creation to his word.","context":"This action fulfils the command of verse 6 and precedes the naming of heaven.","crossReferences":["Psalm 33:6","Jeremiah 10:12"],"application":"Trust that God's purposes are not frustrated by created things.","reviewStatus":"pending"},{"ref":"Genesis 1:8","explanation":"God calls the expanse Heaven, concluding the second day's description.","context":"Here 'heaven' names the expanse described in the immediate passage; the word has other uses elsewhere in Scripture.","crossReferences":["Psalm 19:1","Genesis 1:1"],"application":"Read biblical terms in their immediate context before drawing conclusions.","reviewStatus":"pending"},{"ref":"Genesis 1:9","explanation":"God gathers the waters beneath the heavens so that dry land appears; the command establishes distinct spaces for sea and land.","context":"The third day begins with the emergence of land, preparing for vegetation.","crossReferences":["Psalm 104:7–9","Job 38:8–11"],"application":"Recognise God's authority over forces that appear beyond human control.","reviewStatus":"pending"},{"ref":"Genesis 1:10","explanation":"God names the dry land Earth and the gathered waters Seas, and declares the arrangement good.","context":"The repeated divine evaluation marks the ordered creation as fitting its purpose.","crossReferences":["Psalm 95:5","Psalm 24:1–2"],"application":"Steward land and water with gratitude rather than treating them as ultimate possessions.","reviewStatus":"pending"},{"ref":"Genesis 1:11","explanation":"God commands the earth to bring forth plants that reproduce according to their kinds, including seed-bearing herbs and fruit trees.","context":"Vegetation follows the appearance of dry land on the third day; the text emphasizes provision and continuity.","crossReferences":["Genesis 8:22","Acts 14:17"],"application":"Give thanks for God's provision and care for the resources entrusted to humanity.","reviewStatus":"pending"},{"ref":"Genesis 1:12","explanation":"The earth produces the vegetation God commanded, and God judges it good.","context":"The verse repeats the kinds-and-seed pattern, underscoring the fulfilment of the creative word.","crossReferences":["Psalm 104:14","Matthew 6:28–30"],"application":"Notice ordinary provision as a reason for gratitude to God.","reviewStatus":"pending"},{"ref":"Genesis 1:13","explanation":"Evening and morning conclude the third day, following the appearance of land and vegetation.","context":"This refrain structures the narrative and links the third day with the earlier days.","crossReferences":["Genesis 1:5","Genesis 1:8"],"application":"Practice faithfulness in the regular rhythms of work and rest.","reviewStatus":"pending"},{"ref":"Genesis 1:14","explanation":"God appoints lights in the heavenly expanse to distinguish day and night and to mark seasons, days and years.","context":"The fourth day's account focuses on the functions of heavenly lights in ordering earthly time.","crossReferences":["Psalm 136:7–9","Jeremiah 31:35"],"application":"Use the passing of time wisely, remembering that God is greater than the signs that mark it.","reviewStatus":"pending"},{"ref":"Genesis 1:15","explanation":"The heavenly lights are appointed to shine upon the earth, and God's word is fulfilled.","context":"The verse completes the stated purpose of the lights before the narrative describes their making.","crossReferences":["Psalm 19:1–4","Matthew 5:45"],"application":"Receive the benefits of creation with thanksgiving rather than worshipping created things.","reviewStatus":"pending"},{"ref":"Genesis 1:16","explanation":"God makes the greater and lesser lights to govern day and night, together with the stars.","context":"The narrative describes their roles without naming the sun and moon as deities, in contrast to their worship in some ancient cultures.","crossReferences":["Deuteronomy 4:19","Psalm 8:3"],"application":"Worship the Maker, not the things he has made.","reviewStatus":"pending"},{"ref":"Genesis 1:17","explanation":"God places the lights in the expanse to illuminate the earth.","context":"Their placement serves the earth-focused purpose of the creation account.","crossReferences":["Psalm 74:16","James 1:17"],"application":"Let the order of creation direct praise to God's wisdom.","reviewStatus":"pending"},{"ref":"Genesis 1:18","explanation":"The lights govern day and night and separate light from darkness; God again calls his work good.","context":"The verse restates the functions announced in verse 14 and completes the description before the day's refrain.","crossReferences":["Genesis 1:4","Psalm 136:7–9"],"application":"Remember that divine goodness is the standard by which creation is evaluated.","reviewStatus":"pending"},{"ref":"Genesis 1:19","explanation":"The fourth day ends after God appoints lights to govern the rhythms of earthly time.","context":"The evening-and-morning refrain follows the creation of the heavenly lights.","crossReferences":["Genesis 1:14","Psalm 104:19"],"application":"Use the days God grants with gratitude and purpose.","reviewStatus":"pending"},{"ref":"Genesis 1:20","explanation":"God commands the waters to teem with living creatures and birds to fly above the earth.","context":"The fifth day introduces creatures inhabiting sea and sky, environments ordered earlier.","crossReferences":["Psalm 104:25","Genesis 1:22"],"application":"Value living creatures as part of God's purposeful creation.","reviewStatus":"pending"},{"ref":"Genesis 1:21","explanation":"God creates great sea creatures and every kind of aquatic and flying life, declaring them good.","context":"The description emphasizes abundant varieties of living things rather than naming individual species.","crossReferences":["Psalm 148:7","Nehemiah 9:6"],"application":"Praise God for life beyond human usefulness.","reviewStatus":"pending"},{"ref":"Genesis 1:22","explanation":"God blesses sea creatures and birds with fruitfulness and multiplication.","context":"This is the first explicit blessing in the creation narrative and concerns the flourishing of living creatures.","crossReferences":["Genesis 8:17","Psalm 104:24–25"],"application":"Treat the abundance of life as a blessing to steward responsibly.","reviewStatus":"pending"},{"ref":"Genesis 1:23","explanation":"The fifth day closes with the established evening-and-morning refrain.","context":"The verse marks completion of the sea and sky creatures before the creation of land animals.","crossReferences":["Genesis 1:19","Genesis 1:24"],"application":"Remember God's faithfulness through the ordinary passage of time.","reviewStatus":"pending"},{"ref":"Genesis 1:24","explanation":"God commands the land to bring forth living creatures according to their kinds.","context":"The sixth day begins with livestock, creeping things, and wild animals before the account turns to humanity.","crossReferences":["Genesis 1:25","Psalm 50:10–11"],"application":"Recognize that the earth's creatures belong ultimately to God.","reviewStatus":"pending"},{"ref":"Genesis 1:25","explanation":"God makes the land animals according to their kinds and pronounces them good.","context":"The narrative repeatedly connects the divine command with its fulfilment and God's evaluation.","crossReferences":["Genesis 1:24","Psalm 104:24"],"application":"Respect the goodness of God's creation without making it an object of worship.","reviewStatus":"pending"},{"ref":"Genesis 1:26","explanation":"God announces the creation of humanity in his image and entrusts human beings with responsibility over other creatures.","context":"The deliberative wording marks a transition from the creation of animals to humanity's distinctive calling.","crossReferences":["Psalm 8:4–8","James 3:9"],"application":"Honor every person as bearing God-given dignity and exercise authority responsibly.","reviewStatus":"pending"},{"ref":"Genesis 1:27","explanation":"God creates humanity in his image, explicitly identifying both male and female with that dignity.","context":"The verse expands the announcement of verse 26 and establishes the shared worth of men and women.","crossReferences":["Genesis 5:1–2","Matthew 19:4"],"application":"Treat women and men with equal human dignity before God.","reviewStatus":"pending"},{"ref":"Genesis 1:28","explanation":"God blesses humanity, commands fruitfulness, and assigns stewardship of the earth and its creatures.","context":"The blessing and commission follow humanity's creation in God's image.","crossReferences":["Psalm 8:6–8","Genesis 9:1"],"application":"Exercise responsibility over creation without cruelty or exploitation.","reviewStatus":"pending"},{"ref":"Genesis 1:29","explanation":"God provides seed-bearing plants and fruit-bearing trees for human food.","context":"The provision follows the blessing of humanity and depicts God's care for bodily needs.","crossReferences":["Psalm 104:14","Matthew 6:31–33"],"application":"Receive daily provision thankfully and share with those in need.","reviewStatus":"pending"},{"ref":"Genesis 1:30","explanation":"God assigns green plants as food to land animals and birds that have life.","context":"The verse extends the theme of divine provision beyond humanity to other living creatures.","crossReferences":["Psalm 147:9","Psalm 104:27–28"],"application":"Let God's concern for creatures shape compassionate stewardship.","reviewStatus":"pending"},{"ref":"Genesis 1:31","explanation":"God surveys all he has made and calls it very good, concluding the sixth day.","context":"Unlike earlier evaluations of individual works, this verdict embraces the completed creation account.","crossReferences":["1 Timothy 4:4","Psalm 104:24"],"application":"Give thanks for creation while remembering that the Creator deserves supreme worship.","reviewStatus":"pending"},{"ref":"Genesis 2:1","explanation":"The heavens and earth and their hosts are presented as completed.","context":"The verse summarizes the six-day creation narrative before describing the seventh day.","crossReferences":["Genesis 1:31","Nehemiah 9:6"],"application":"Recognize creation as God's work and respond with worship.","reviewStatus":"pending"},{"ref":"Genesis 2:2","explanation":"God finishes his creative work and rests on the seventh day.","context":"Divine rest signifies cessation from creation, not exhaustion.","crossReferences":["Exodus 20:11","Hebrews 4:4"],"application":"Make room for worship and trust rather than endless striving.","reviewStatus":"pending"},{"ref":"Genesis 2:3","explanation":"God blesses and sanctifies the seventh day because he rested from creation.","context":"The first explicitly sanctified time in Genesis becomes foundational to later Sabbath teaching.","crossReferences":["Exodus 20:8–11","Mark 2:27"],"application":"Set apart time for honoring God.","reviewStatus":"pending"},{"ref":"Genesis 2:4","explanation":"The account turns to the generations of heaven and earth when God made them.","context":"This heading introduces a closer portrayal of the earthly setting and humanity's beginnings.","crossReferences":["Genesis 1:1","Genesis 5:1"],"application":"Read the following narrative alongside the broad creation account.","reviewStatus":"pending"},{"ref":"Genesis 2:5","explanation":"The text describes the earth before cultivated plants and human tillage, when rain had not yet fallen.","context":"The focus narrows from cosmic creation to the conditions surrounding human cultivation.","crossReferences":["Genesis 2:15","Genesis 3:23"],"application":"Remember humanity's dependence on God's provision for fruitful work.","reviewStatus":"pending"},{"ref":"Genesis 2:6","explanation":"Water rises from the earth and moistens the ground.","context":"The narrative describes the ground's watering before the garden and human vocation are introduced.","crossReferences":["Psalm 104:10–14","Genesis 2:5"],"application":"Give thanks for the ordinary means by which God sustains life.","reviewStatus":"pending"},{"ref":"Genesis 2:7","explanation":"God forms the man from ground dust and breathes life into him.","context":"The image unites humanity's earthly origin with life received from God.","crossReferences":["Genesis 3:19","Job 33:4"],"application":"Practice humility and gratitude for the gift of life.","reviewStatus":"pending"},{"ref":"Genesis 2:8","explanation":"God plants a garden in Eden and places the man there.","context":"The garden provides the setting for human work, fellowship and moral responsibility.","crossReferences":["Genesis 2:15","Ezekiel 28:13"],"application":"Receive God's gifts as responsibilities to steward.","reviewStatus":"pending"},{"ref":"Genesis 2:9","explanation":"God makes beautiful and nourishing trees grow, including the tree of life and the tree of the knowledge of good and evil.","context":"The named trees introduce the moral choice developed later in the chapter.","crossReferences":["Genesis 2:16–17","Revelation 22:2"],"application":"Enjoy God's provision without ignoring his commands.","reviewStatus":"pending"},{"ref":"Genesis 2:10","explanation":"A river flows from Eden to water the garden and then divides into four branches.","context":"The geographical description portrays Eden as a well-watered place; precise modern identifications remain debated.","crossReferences":["Genesis 13:10","Psalm 46:4"],"application":"Avoid claiming certainty about ancient geography beyond the text.","reviewStatus":"pending"},{"ref":"Genesis 2:11","explanation":"The first river is named Pison and is described as surrounding Havilah.","context":"This is the first of four river descriptions; the precise location is uncertain.","crossReferences":["Genesis 2:10","Genesis 25:18"],"application":"Distinguish what Scripture states from later geographic speculation.","reviewStatus":"pending"},{"ref":"Genesis 2:12","explanation":"Havilah is associated with gold, described here as good.","context":"The account briefly notes the region's natural resources.","crossReferences":["Genesis 2:11","Psalm 24:1"],"application":"Value resources without allowing wealth to replace devotion to God.","reviewStatus":"pending"},{"ref":"Genesis 2:13","explanation":"Bdellium and onyx are listed among the region's notable materials.","context":"The verse completes the description of Havilah's resources.","crossReferences":["Genesis 2:12","Exodus 28:9"],"application":"Remember that material beauty belongs within God's created world.","reviewStatus":"pending"},{"ref":"Genesis 2:14","explanation":"The second river is named Gihon and associated with Cush.","context":"Ancient geographic names do not necessarily map neatly onto modern borders.","crossReferences":["Genesis 2:10","Genesis 10:6"],"application":"Approach uncertain historical identifications with care.","reviewStatus":"pending"},{"ref":"Genesis 2:15","explanation":"The third river is Hiddekel, described as flowing east of Assyria, and the fourth is Euphrates.","context":"Hiddekel is commonly associated with the Tigris; the river list closes the Eden description.","crossReferences":["Daniel 10:4","Genesis 15:18"],"application":"Let geographical detail illuminate Scripture without overshadowing its message.","reviewStatus":"pending"},{"ref":"Genesis 2:16","explanation":"God places the man in Eden to dress and keep the garden.","context":"Human work and responsibility appear before the account of disobedience.","crossReferences":["Genesis 1:28","Colossians 3:23"],"application":"Treat honest labor and stewardship as meaningful service.","reviewStatus":"pending"},{"ref":"Genesis 2:17","explanation":"God commands the man concerning what he may eat in the garden.","context":"The permission is broad and precedes the specific prohibition in the next verse.","crossReferences":["Genesis 2:9","1 Timothy 4:4"],"application":"Notice God's generosity as well as his boundaries.","reviewStatus":"pending"},{"ref":"Genesis 2:18","explanation":"God forbids eating from one tree and warns of death as the consequence.","context":"The command introduces accountable moral choice within God's generous provision.","crossReferences":["Genesis 3:3","Romans 6:23"],"application":"Take God's commands seriously rather than testing their limits.","reviewStatus":"pending"},{"ref":"Genesis 2:19","explanation":"God declares that it is not good for the man to be alone and promises a suitable helper.","context":"The statement contrasts with the repeated goodness of creation and anticipates human companionship.","crossReferences":["Genesis 2:20","Ecclesiastes 4:9–10"],"application":"Value faithful companionship and mutual support.","reviewStatus":"pending"},{"ref":"Genesis 2:20","explanation":"God brings formed animals to the man to see what he will call them.","context":"Naming depicts the man's active responsibility within creation.","crossReferences":["Genesis 1:28","Psalm 8:6–8"],"application":"Use entrusted authority thoughtfully and kindly.","reviewStatus":"pending"},{"ref":"Genesis 2:21","explanation":"God causes Adam to sleep, takes a rib from his side and closes the flesh, beginning the creation of the woman.","context":"The act follows the observation that no suitable companion was found among the animals.","crossReferences":["Genesis 2:20","Genesis 2:22"],"application":"Respect God's design for human companionship.","reviewStatus":"pending"},{"ref":"Genesis 2:22","explanation":"God forms the woman from what He took from the man and brings her to him.","context":"The verse completes the action begun in verse 21 and presents the woman as God's provision.","crossReferences":["Genesis 2:21","1 Corinthians 11:8"],"application":"Honor the equal human dignity of women and men.","reviewStatus":"pending"},{"ref":"Genesis 2:23","explanation":"Adam recognizes the woman as bone of his bones and flesh of his flesh, celebrating their shared humanity.","context":"Adam's words follow God's presentation of the woman and precede the statement about marriage.","crossReferences":["Genesis 2:22","Ephesians 5:28"],"application":"Treat others with respect and recognize shared human dignity.","reviewStatus":"pending"},{"ref":"Genesis 2:24","explanation":"The verse establishes leaving one's parents and cleaving to one's wife as the pattern of a one-flesh marriage union.","context":"This concluding statement draws a principle from the creation of woman and is later cited by Jesus.","crossReferences":["Matthew 19:5","Ephesians 5:31"],"application":"Approach marriage with faithfulness and lifelong responsibility.","reviewStatus":"pending"},{"ref":"Genesis 2:25","explanation":"The man and woman are naked without shame, depicting their unbroken openness before the events of Genesis 3.","context":"The peaceful conclusion to Genesis 2 contrasts with their shame and concealment after disobedience.","crossReferences":["Genesis 3:7","Genesis 3:10"],"application":"Value honesty and integrity before God.","reviewStatus":"pending"},{"ref":"Genesis 3:1","explanation":"The serpent questions God's command in conversation with the woman.","context":"The narrative introduces temptation through a distortion of what God said.","crossReferences":["Genesis 2:16–17","2 Corinthians 11:3"],"application":"Test persuasive claims against God's word.","reviewStatus":"pending"},{"ref":"Genesis 3:2","explanation":"The woman answers that fruit from the garden's trees may be eaten.","context":"Her reply recalls God's broad permission before naming the forbidden tree.","crossReferences":["Genesis 2:16","Genesis 3:3"],"application":"Remember God's generosity when confronting temptation.","reviewStatus":"pending"},{"ref":"Genesis 3:3","explanation":"The woman recounts the prohibition concerning the central tree and its consequence.","context":"Her reported wording differs from the original command, which should be compared carefully.","crossReferences":["Genesis 2:17","Deuteronomy 4:2"],"application":"Handle God's instructions accurately.","reviewStatus":"pending"},{"ref":"Genesis 3:4","explanation":"The serpent directly contradicts God's warning about death.","context":"The deception attacks confidence in God's truthfulness.","crossReferences":["Genesis 2:17","John 8:44"],"application":"Reject assurances that make disobedience appear harmless.","reviewStatus":"pending"},{"ref":"Genesis 3:5","explanation":"The serpent promises opened eyes and godlike knowledge of good and evil.","context":"The temptation presents independence from God's command as advancement.","crossReferences":["Genesis 3:22","James 1:14–15"],"application":"Do not confuse spiritual pride with wisdom.","reviewStatus":"pending"},{"ref":"Genesis 3:6","explanation":"The woman sees the fruit as desirable, takes it, eats, and gives it to her husband, who also eats.","context":"The verse describes the decisive act of disobedience by both humans.","crossReferences":["Romans 5:12","1 Timothy 2:14"],"application":"Recognize how desire can become disobedience when unchecked.","reviewStatus":"pending"},{"ref":"Genesis 3:7","explanation":"Their eyes are opened to their nakedness, and they fashion coverings.","context":"The immediate result is shame and attempted self-covering rather than the promised freedom.","crossReferences":["Genesis 2:25","Genesis 3:21"],"application":"Bring wrongdoing into God's light instead of relying on appearances.","reviewStatus":"pending"},{"ref":"Genesis 3:8","explanation":"The man and woman hide when they hear God in the garden.","context":"The scene portrays a broken relationship after disobedience.","crossReferences":["Genesis 3:10","Psalm 139:7–12"],"application":"Do not hide from God when repentance is needed.","reviewStatus":"pending"},{"ref":"Genesis 3:9","explanation":"God calls to the man and asks where he is.","context":"The question begins an encounter that exposes the human response to sin.","crossReferences":["Genesis 3:10–11","Luke 15:20"],"application":"Respond honestly when conscience is awakened.","reviewStatus":"pending"},{"ref":"Genesis 3:10","explanation":"The man admits fear and hiding because he was naked.","context":"Fear replaces the earlier unashamed openness.","crossReferences":["Genesis 2:25","1 John 4:18"],"application":"Seek reconciliation with God rather than remaining in fear.","reviewStatus":"pending"},{"ref":"Genesis 3:11","explanation":"God questions how the man knew he was naked and whether he ate from the forbidden tree.","context":"The questions direct attention to the specific command that was broken.","crossReferences":["Genesis 2:17","Genesis 3:6"],"application":"Accept responsibility for choices instead of evading the issue.","reviewStatus":"pending"},{"ref":"Genesis 3:12","explanation":"The man blames the woman and indirectly points to God while admitting he ate.","context":"His reply shows how sin can distort accountability and relationships.","crossReferences":["Genesis 3:6","Proverbs 28:13"],"application":"Confess wrongdoing without shifting blame.","reviewStatus":"pending"},{"ref":"Genesis 3:13","explanation":"God asks the woman what she has done, and she says the serpent deceived her.","context":"Her response identifies deception while acknowledging the act of eating.","crossReferences":["Genesis 3:1–6","2 Corinthians 11:3"],"application":"Learn to recognize deception and own your decisions.","reviewStatus":"pending"},{"ref":"Genesis 3:14","explanation":"God pronounces judgment upon the serpent, including humiliation and hostility.","context":"The first judgment is directed to the deceiver before the consequences for humanity are described.","crossReferences":["Genesis 3:15","Revelation 12:9"],"application":"Remember that evil does not escape God's judgment.","reviewStatus":"pending"},{"ref":"Genesis 3:15","explanation":"God declares hostility between the serpent's seed and the woman's seed, with a future conflict and victory.","context":"Christian readers commonly see a first anticipation of Christ's victory, while the immediate language remains part of the serpent judgment.","crossReferences":["Romans 16:20","Hebrews 2:14"],"application":"Place hope in God's promised triumph over evil.","reviewStatus":"pending"},{"ref":"Genesis 3:16","explanation":"God describes increased pain and tension in the woman's experience of childbearing and relationship.","context":"The verse records consequences of the fall, not a command to inflict suffering or justify abuse.","crossReferences":["Genesis 4:7","Ephesians 5:25"],"application":"Reject domination and practice care in human relationships.","reviewStatus":"pending"},{"ref":"Genesis 3:17","explanation":"God confronts Adam for heeding the forbidden invitation and declares the ground cursed on his account.","context":"Human disobedience now affects the labor by which food is obtained.","crossReferences":["Genesis 2:17","Romans 8:20–22"],"application":"Recognize sin's consequences while continuing responsible work.","reviewStatus":"pending"},{"ref":"Genesis 3:18","explanation":"The ground will produce thorns and thistles as the man eats its plants.","context":"The description expands the hardship of cultivation after the fall.","crossReferences":["Genesis 2:15","Hebrews 6:8"],"application":"Persevere in honest labor despite difficulty.","reviewStatus":"pending"},{"ref":"Genesis 3:19","explanation":"Human life will involve strenuous labor and ultimately return to dust.","context":"The warning recalls humanity's origin from the ground and mortality after sin.","crossReferences":["Genesis 2:7","Ecclesiastes 12:7"],"application":"Live humbly and use life for what matters eternally.","reviewStatus":"pending"},{"ref":"Genesis 3:20","explanation":"Adam names his wife Eve because she is mother of all living.","context":"The naming follows the judgment narrative and looks toward the continuation of human life.","crossReferences":["Genesis 4:1","Acts 17:26"],"application":"Respect the shared humanity of all people.","reviewStatus":"pending"},{"ref":"Genesis 3:21","explanation":"God clothes Adam and Eve with garments of skin.","context":"The divine provision replaces the inadequate coverings they made for themselves.","crossReferences":["Genesis 3:7","Isaiah 61:10"],"application":"Receive God's mercy with gratitude without inventing details the text does not state.","reviewStatus":"pending"},{"ref":"Genesis 3:22","explanation":"God speaks of humanity's acquired knowledge of good and evil and guards against eating from the tree of life.","context":"The statement leads directly to exclusion from Eden.","crossReferences":["Genesis 2:9","Genesis 3:23"],"application":"Recognize the seriousness of seeking life apart from God's will.","reviewStatus":"pending"},{"ref":"Genesis 3:23","explanation":"God sends the man out of Eden to cultivate the ground from which he came.","context":"The expulsion fulfills the preceding decision and changes humanity's place of work.","crossReferences":["Genesis 2:15","Genesis 3:19"],"application":"Continue faithful responsibilities even amid consequences.","reviewStatus":"pending"},{"ref":"Genesis 3:24","explanation":"God stations cherubim and a flaming sword to guard access to the tree of life.","context":"The closing verse emphasizes the lost access to Eden and the seriousness of separation.","crossReferences":["Genesis 2:9","Revelation 22:14"],"application":"Look to God's provision of life rather than self-made access.","reviewStatus":"pending"},{"ref":"Genesis 4:1","explanation":"Adam and Eve's first son Cain is born, and Eve acknowledges the LORD's help.","context":"The narrative moves from Eden to the first human family outside the garden.","crossReferences":["Genesis 3:20","Psalm 127:3"],"application":"Receive children as gifts without assuming their future choices.","reviewStatus":"pending"},{"ref":"Genesis 4:2","explanation":"Abel is born and becomes a keeper of sheep while Cain works the ground.","context":"The brothers' different occupations introduce the offerings that follow.","crossReferences":["Genesis 2:15","Genesis 4:3–4"],"application":"Respect honorable forms of work.","reviewStatus":"pending"},{"ref":"Genesis 4:3","explanation":"Cain brings an offering from the fruit of the ground to the LORD.","context":"The passage does not explicitly say that all produce offerings are unacceptable.","crossReferences":["Leviticus 2:1","Hebrews 11:4"],"application":"Examine the faith and attitude with which you worship.","reviewStatus":"pending"},{"ref":"Genesis 4:4","explanation":"Abel offers from the firstlings of his flock and their fat, and God regards him and his offering.","context":"Hebrews later highlights Abel's faith; the narrative links divine regard to the worshipper as well as the gift.","crossReferences":["Hebrews 11:4","Proverbs 3:9"],"application":"Offer God sincere, faithful devotion.","reviewStatus":"pending"},{"ref":"Genesis 4:5","explanation":"God does not regard Cain and his offering, and Cain becomes angry.","context":"The text reports the response but does not explicitly explain every reason for the rejection.","crossReferences":["Genesis 4:6–7","1 John 3:12"],"application":"Respond to correction with humility rather than resentment.","reviewStatus":"pending"},{"ref":"Genesis 4:6","explanation":"God asks Cain why he is angry and why his face has fallen.","context":"The questions offer Cain an opportunity to examine his response before acting.","crossReferences":["Genesis 3:9","James 1:19–20"],"application":"Bring anger under control before it shapes your conduct.","reviewStatus":"pending"},{"ref":"Genesis 4:7","explanation":"God warns Cain that sin is crouching at the door and calls him to master it.","context":"The warning presents Cain as responsible for his next choice despite powerful temptation.","crossReferences":["James 1:14–15","Romans 6:12"],"application":"Resist temptation early rather than nurturing it.","reviewStatus":"pending"},{"ref":"Genesis 4:8","explanation":"Cain attacks and kills his brother Abel in the field.","context":"The first recorded killing follows unresolved anger and jealousy.","crossReferences":["Matthew 5:21–22","1 John 3:12"],"application":"Reject envy and seek peaceful resolution of conflict.","reviewStatus":"pending"},{"ref":"Genesis 4:9","explanation":"God asks Cain where Abel is, and Cain denies responsibility for his brother.","context":"The evasive answer echoes the failure to take responsibility after the fall.","crossReferences":["Genesis 3:12","Proverbs 28:13"],"application":"Care about others and speak truthfully.","reviewStatus":"pending"},{"ref":"Genesis 4:10","explanation":"God declares that Abel's blood cries from the ground.","context":"The image expresses the gravity of innocent bloodshed before the divine Judge.","crossReferences":["Hebrews 12:24","Revelation 6:10"],"application":"Remember that injustice matters to God.","reviewStatus":"pending"},{"ref":"Genesis 4:11","explanation":"Cain is cursed from the ground that received his brother's blood.","context":"The punishment connects the violence to Cain's livelihood as a cultivator.","crossReferences":["Genesis 3:17","Numbers 35:33"],"application":"Recognize that wrongdoing damages both people and communities.","reviewStatus":"pending"},{"ref":"Genesis 4:12","explanation":"Cain's labor will no longer yield as before, and he will be a fugitive.","context":"The consequences affect both his work and his settled place in society.","crossReferences":["Genesis 4:14","Psalm 107:4"],"application":"Choose righteousness over short-term anger.","reviewStatus":"pending"},{"ref":"Genesis 4:13","explanation":"Cain protests that his punishment is too great to bear.","context":"His complaint emphasizes suffering but does not record a clear confession of repentance.","crossReferences":["Genesis 4:14","Psalm 51:3–4"],"application":"Do not confuse regret over consequences with repentance.","reviewStatus":"pending"},{"ref":"Genesis 4:14","explanation":"Cain fears separation from God's presence and retaliation by others.","context":"The verse shows his fear of vulnerability after being sent away.","crossReferences":["Genesis 4:12","Genesis 9:6"],"application":"Seek God's mercy without minimizing wrongdoing.","reviewStatus":"pending"},{"ref":"Genesis 4:15","explanation":"God protects Cain from immediate revenge by appointing a sign.","context":"The nature of the mark is not specified and should not be linked to any ethnicity or skin color.","crossReferences":["Romans 12:19","Genesis 4:24"],"application":"Leave vengeance to God and reject invented interpretations.","reviewStatus":"pending"},{"ref":"Genesis 4:16","explanation":"Cain leaves the LORD's presence and lives in Nod, east of Eden.","context":"The movement away from Eden continues the theme of estrangement after sin.","crossReferences":["Genesis 3:24","Isaiah 59:2"],"application":"Pursue reconciliation with God rather than separation.","reviewStatus":"pending"},{"ref":"Genesis 4:17","explanation":"Cain fathers Enoch and names a city after him.","context":"The account traces early settlement and family development outside Eden.","crossReferences":["Genesis 4:18","Psalm 127:1"],"application":"Build communities with justice and accountability.","reviewStatus":"pending"},{"ref":"Genesis 4:18","explanation":"The genealogy names Irad, Mehujael, Methusael and Lamech.","context":"The line of Cain is traced briefly before the narrative describes Lamech's household.","crossReferences":["Genesis 4:17","Genesis 4:19"],"application":"Remember that genealogies record people without endorsing every action.","reviewStatus":"pending"},{"ref":"Genesis 4:19","explanation":"Lamech takes two wives, Adah and Zillah.","context":"The narrative reports polygamy without explicitly praising it; Genesis 2 portrays the original marriage union.","crossReferences":["Genesis 2:24","Matthew 19:4–6"],"application":"Distinguish biblical description from moral approval.","reviewStatus":"pending"},{"ref":"Genesis 4:20","explanation":"Adah gives birth to Jabal, described as ancestor of tent-dwelling livestock keepers.","context":"The passage identifies the development of pastoral ways of life.","crossReferences":["Genesis 4:21","Genesis 2:15"],"application":"Use practical skills for the good of others.","reviewStatus":"pending"},{"ref":"Genesis 4:21","explanation":"Jubal is identified with those who play harp and organ.","context":"The verse associates the family with early musical arts and instruments.","crossReferences":["Psalm 150:3–5","Genesis 4:20"],"application":"Use musical ability responsibly and to honor God.","reviewStatus":"pending"},{"ref":"Genesis 4:22","explanation":"Zillah bears Tubalcain, a worker in bronze and iron, and names his sister Naamah.","context":"The account records technological crafts alongside the development of human society.","crossReferences":["Exodus 31:3–5","Genesis 4:21"],"application":"Direct technical skill toward constructive purposes.","reviewStatus":"pending"},{"ref":"Genesis 4:23","explanation":"Lamech tells his wives that he has killed a man for wounding him.","context":"His speech illustrates an escalating attitude toward retaliatory violence.","crossReferences":["Genesis 4:8","Matthew 5:38–39"],"application":"Reject pride in revenge and choose restraint.","reviewStatus":"pending"},{"ref":"Genesis 4:24","explanation":"Lamech claims a vengeance greater than Cain's promised protection.","context":"The boast contrasts divine restraint on retaliation with human glorification of it.","crossReferences":["Genesis 4:15","Romans 12:19"],"application":"Do not turn God's mercy into an excuse for violence.","reviewStatus":"pending"},{"ref":"Genesis 4:25","explanation":"Adam and Eve have Seth, whom Eve associates with a replacement for Abel.","context":"The family narrative resumes after Abel's death and Cain's departure.","crossReferences":["Genesis 4:8","Genesis 5:3"],"application":"Look to God's continuing provision amid grief.","reviewStatus":"pending"},{"ref":"Genesis 4:26","explanation":"Seth fathers Enos, and people begin to call upon the name of the LORD.","context":"The verse closes the chapter by highlighting worship in Seth's line.","crossReferences":["Genesis 12:8","Joel 2:32"],"application":"Call upon God sincerely and openly.","reviewStatus":"pending"},{"ref":"Genesis 5:1","explanation":"The genealogy of Adam begins by recalling that God created humanity in his likeness.","context":"The chapter connects the human family line with the creation account.","crossReferences":["Genesis 1:26–27","James 3:9"],"application":"Remember the God-given dignity of every person.","reviewStatus":"pending"},{"ref":"Genesis 5:2","explanation":"God created male and female, blessed them and called them Adam in the day of creation.","context":"The verse restates the shared human identity established in Genesis 1.","crossReferences":["Genesis 1:27–28","Matthew 19:4"],"application":"Treat women and men with dignity.","reviewStatus":"pending"},{"ref":"Genesis 5:3","explanation":"At 130 years Adam fathers Seth, a son in his likeness and image.","context":"The wording echoes creation language while introducing the genealogy's main line.","crossReferences":["Genesis 4:25","Genesis 5:1"],"application":"Consider the responsibility of passing on faith and character.","reviewStatus":"pending"},{"ref":"Genesis 5:4","explanation":"Adam lives 800 more years after Seth and has other sons and daughters.","context":"The genealogy mentions a wider family beyond its named line.","crossReferences":["Genesis 5:5","Genesis 1:28"],"application":"Avoid assuming the named children were the only children.","reviewStatus":"pending"},{"ref":"Genesis 5:5","explanation":"Adam dies at 930 years of age.","context":"The recurring death notice underscores human mortality after the fall.","crossReferences":["Genesis 3:19","Romans 5:12"],"application":"Live with eternity in view.","reviewStatus":"pending"},{"ref":"Genesis 5:6","explanation":"Seth is 105 years old when Enos is born.","context":"The genealogy proceeds from Adam through Seth to the next generation.","crossReferences":["Genesis 4:26","Genesis 5:3"],"application":"Recognize each generation's place in a larger story.","reviewStatus":"pending"},{"ref":"Genesis 5:7","explanation":"Seth lives another 807 years and has other sons and daughters.","context":"The formula emphasizes family continuity while preserving one named line.","crossReferences":["Genesis 5:8","Psalm 90:12"],"application":"Use the years entrusted to you wisely.","reviewStatus":"pending"},{"ref":"Genesis 5:8","explanation":"Seth dies at 912 years of age.","context":"The repeated refrain of death interrupts the record of long lifespans.","crossReferences":["Genesis 5:5","Hebrews 9:27"],"application":"Do not mistake long life for immortality.","reviewStatus":"pending"},{"ref":"Genesis 5:9","explanation":"Enos fathers Cainan at 90 years of age.","context":"The genealogy follows the line introduced at the close of Genesis 4.","crossReferences":["Genesis 4:26","Luke 3:37–38"],"application":"Read biblical genealogies attentively rather than dismissing them.","reviewStatus":"pending"},{"ref":"Genesis 5:10","explanation":"Enos lives 815 more years and has sons and daughters.","context":"The record acknowledges descendants not individually named.","crossReferences":["Genesis 5:9","Genesis 5:11"],"application":"Value people beyond those named in prominent records.","reviewStatus":"pending"},{"ref":"Genesis 5:11","explanation":"Enos dies at 905 years of age.","context":"The repeated ending emphasizes the mortality of each generation.","crossReferences":["Genesis 5:8","Psalm 90:10"],"application":"Remember that human life has limits.","reviewStatus":"pending"},{"ref":"Genesis 5:12","explanation":"Cainan fathers Mahalaleel at 70 years of age.","context":"The ancestral line continues toward Enoch and Noah.","crossReferences":["Genesis 5:13","Luke 3:37"],"application":"Recognize the continuity of God's dealings across generations.","reviewStatus":"pending"},{"ref":"Genesis 5:13","explanation":"Cainan lives another 840 years and has other children.","context":"The text maintains its pattern of age, descendants and lifespan.","crossReferences":["Genesis 5:12","Genesis 5:14"],"application":"Steward your life without making fame your measure.","reviewStatus":"pending"},{"ref":"Genesis 5:14","explanation":"Cainan dies at 910 years of age.","context":"The recurring notice of death continues the chapter's central pattern.","crossReferences":["Genesis 3:19","Genesis 5:11"],"application":"Face mortality with humility before God.","reviewStatus":"pending"},{"ref":"Genesis 5:15","explanation":"Mahalaleel fathers Jared at 65 years of age.","context":"This entry advances the genealogy one generation.","crossReferences":["Genesis 5:16","Luke 3:37"],"application":"Read the names as part of the Bible's historical narrative.","reviewStatus":"pending"},{"ref":"Genesis 5:16","explanation":"Mahalaleel lives another 830 years and has sons and daughters.","context":"The unnamed descendants show that the genealogy is selective.","crossReferences":["Genesis 5:15","Genesis 5:17"],"application":"Do not equate limited written detail with limited human worth.","reviewStatus":"pending"},{"ref":"Genesis 5:17","explanation":"Mahalaleel dies at 895 years of age.","context":"The death refrain again marks the limit of a lengthy life.","crossReferences":["Genesis 5:14","Psalm 90:12"],"application":"Number your days wisely.","reviewStatus":"pending"},{"ref":"Genesis 5:18","explanation":"Jared fathers Enoch at 162 years of age.","context":"Enoch's story will interrupt the normal death formula of the genealogy.","crossReferences":["Genesis 5:21–24","Hebrews 11:5"],"application":"Pay attention when biblical patterns change.","reviewStatus":"pending"},{"ref":"Genesis 5:19","explanation":"Jared lives 800 more years and has other children.","context":"The record gives Jared's remaining years before his total lifespan.","crossReferences":["Genesis 5:18","Genesis 5:20"],"application":"Use life's seasons faithfully.","reviewStatus":"pending"},{"ref":"Genesis 5:20","explanation":"Jared dies at 962 years of age.","context":"His death continues the genealogy's repeated reminder of mortality.","crossReferences":["Genesis 5:17","Hebrews 9:27"],"application":"Do not place ultimate hope in earthly longevity.","reviewStatus":"pending"},{"ref":"Genesis 5:21","explanation":"Enoch fathers Methuselah at 65 years of age.","context":"The genealogy now turns to a man distinguished by walking with God.","crossReferences":["Genesis 5:22","Jude 14"],"application":"Pursue faithful living in ordinary family life.","reviewStatus":"pending"},{"ref":"Genesis 5:22","explanation":"Enoch walks with God for 300 years after Methuselah's birth and has other children.","context":"The phrase 'walked with God' highlights his relationship with God amid family responsibilities.","crossReferences":["Micah 6:8","Hebrews 11:5"],"application":"Practice steady obedience over time.","reviewStatus":"pending"},{"ref":"Genesis 5:23","explanation":"Enoch's recorded years total 365.","context":"The brief numerical summary precedes the unusual conclusion to his life.","crossReferences":["Genesis 5:24","Hebrews 11:5"],"application":"Measure faithfulness by relationship with God, not merely years lived.","reviewStatus":"pending"},{"ref":"Genesis 5:24","explanation":"Enoch walks with God and is no more because God takes him.","context":"Unlike surrounding entries, the verse does not conclude 'and he died'; Hebrews interprets his taking as translation.","crossReferences":["Hebrews 11:5","Genesis 5:22"],"application":"Seek to walk with God faithfully.","reviewStatus":"pending"},{"ref":"Genesis 5:25","explanation":"Methuselah fathers Lamech at 187 years of age.","context":"The genealogy proceeds from Enoch toward Noah.","crossReferences":["Genesis 5:26","Luke 3:36–37"],"application":"Remember that faith is lived across generations.","reviewStatus":"pending"},{"ref":"Genesis 5:26","explanation":"Methuselah lives another 782 years and has other children.","context":"The verse supplies the remaining years of the man later given the longest recorded lifespan in the chapter.","crossReferences":["Genesis 5:25","Genesis 5:27"],"application":"Use longevity as an opportunity for responsibility.","reviewStatus":"pending"},{"ref":"Genesis 5:27","explanation":"Methuselah dies at 969 years of age.","context":"Even the longest lifespan in this genealogy ends with death.","crossReferences":["Genesis 3:19","Psalm 90:12"],"application":"Seek lasting hope beyond the length of earthly life.","reviewStatus":"pending"},{"ref":"Genesis 5:28","explanation":"Lamech fathers a son at 182 years of age.","context":"The child is named in the next verse as Noah.","crossReferences":["Genesis 5:29","Genesis 6:8"],"application":"Look for God's work in the next generation.","reviewStatus":"pending"},{"ref":"Genesis 5:29","explanation":"Lamech names the child Noah and expresses hope for comfort from toil on cursed ground.","context":"The naming explicitly recalls the curse on the ground in Genesis 3.","crossReferences":["Genesis 3:17–19","Genesis 8:21"],"application":"Bring weariness and hope honestly before God.","reviewStatus":"pending"},{"ref":"Genesis 5:30","explanation":"Lamech lives another 595 years and has other sons and daughters.","context":"The genealogy distinguishes Noah while acknowledging a wider family.","crossReferences":["Genesis 5:28","Genesis 5:31"],"application":"Recognize that a family story includes unnamed lives.","reviewStatus":"pending"},{"ref":"Genesis 5:31","explanation":"Lamech dies at 777 years of age.","context":"The repeated death notice precedes the final entry introducing Noah.","crossReferences":["Genesis 5:27","Hebrews 9:27"],"application":"Remember that earthly generations pass.","reviewStatus":"pending"},{"ref":"Genesis 5:32","explanation":"Noah is 500 years old and fathers Shem, Ham and Japheth.","context":"The chapter ends by naming the sons central to the coming flood narrative.","crossReferences":["Genesis 6:10","Genesis 9:18"],"application":"Prepare to read the following account in its family context.","reviewStatus":"pending"},{"ref":"Genesis 6:1","explanation":"Human families increase across the earth, setting the scene for the moral crisis described in the following verses.","context":"The chapter opens after the genealogies of Genesis 5 and moves from family succession to conditions in the wider human community.","crossReferences":["Genesis 5:1","Genesis 6:5"],"application":"Growth in population is no substitute for growth in righteousness.","reviewStatus":"pending"},{"ref":"Genesis 6:2","explanation":"The verse describes unions chosen by the 'sons of God' with the 'daughters of men'; the identity of the sons is debated, and the passage does not resolve every interpretive question.","context":"Several interpretations have been offered, including godly-line and heavenly-being readings. The immediate narrative emphasizes escalating disorder before the flood.","crossReferences":["Genesis 6:1","Matthew 24:38"],"application":"Avoid building certain doctrines on details that Scripture leaves disputed.","reviewStatus":"pending"},{"ref":"Genesis 6:3","explanation":"God announces a limit to His continued striving with humanity and mentions one hundred and twenty years; whether this describes a warning period or a lifespan limit is debated.","context":"The declaration precedes the description of pervasive wickedness and the announcement of judgment. The text stresses that divine patience should not be presumed upon.","crossReferences":["Genesis 6:5","1 Peter 3:20"],"application":"Respond to God's warning promptly rather than assuming opportunities will remain indefinitely.","reviewStatus":"pending"},{"ref":"Genesis 6:4","explanation":"The passage recalls renowned mighty figures and 'giants' in the ancient world, but does not supply enough information to settle their precise identity or origin.","context":"It continues the difficult account of verses 1–2. Interpretations of the Nephilim differ, so claims about their nature require caution.","crossReferences":["Genesis 6:2","Numbers 13:33"],"application":"Do not let speculation about extraordinary figures obscure the chapter's warning about sin.","reviewStatus":"pending"},{"ref":"Genesis 6:5","explanation":"God sees wickedness not merely in public conduct but in the persistent direction of human thoughts and desires.","context":"The moral assessment explains the coming judgment. The focus on the heart anticipates biblical teaching that sin reaches inward motives.","crossReferences":["Jeremiah 17:9","Matthew 15:19"],"application":"Ask God to examine inward motives as well as outward actions.","reviewStatus":"pending"},{"ref":"Genesis 6:6","explanation":"The language of divine grief conveys God's holy opposition to human evil; it does not mean God was surprised by events or ceased to be sovereign.","context":"The verse follows God's assessment of pervasive wickedness and precedes the announcement of judgment.","crossReferences":["Genesis 6:5","Ephesians 4:30"],"application":"Take seriously that human conduct matters before the holy God.","reviewStatus":"pending"},{"ref":"Genesis 6:7","explanation":"God declares judgment upon a corrupted world, extending the effects of human rebellion throughout the living order described in creation.","context":"The judgment reverses the flourishing of life described in Genesis 1. The next verse introduces a striking contrast through Noah.","crossReferences":["Genesis 1:24","Genesis 6:8"],"application":"Recognize the seriousness of sin and seek God's mercy.","reviewStatus":"pending"},{"ref":"Genesis 6:8","explanation":"Noah receives favour from the LORD amid widespread corruption; the account turns from judgment to God's gracious provision.","context":"The contrast with verse 7 prepares the narrative of Noah's walk with God and the preservation of life.","crossReferences":["Genesis 6:7","Hebrews 11:7"],"application":"Depend on God's grace rather than trusting personal merit.","reviewStatus":"pending"},{"ref":"Genesis 6:9","explanation":"Noah is described as just and blameless in his generation, and his life is characterized by walking with God; this is not a claim that he never sinned.","context":"The description follows the statement that Noah found grace, presenting faithful conduct within a corrupt age.","crossReferences":["Genesis 6:8","Genesis 5:24"],"application":"Pursue consistent obedience even when surrounding culture moves in another direction.","reviewStatus":"pending"},{"ref":"Genesis 6:10","explanation":"Noah's three sons are named as the family through whom the post-flood generations will be traced.","context":"The genealogy connects the account of Noah to the nations listed later in Genesis 10.","crossReferences":["Genesis 5:32","Genesis 10:1"],"application":"Remember that faithfulness and decisions can shape the lives of future generations.","reviewStatus":"pending"},{"ref":"Genesis 6:11","explanation":"The earth is described as corrupt before God and filled with violence, making clear that evil has become socially destructive.","context":"The repeated language of corruption and violence provides the moral basis for the flood announcement.","crossReferences":["Genesis 6:5","Genesis 6:13"],"application":"Reject violence and injustice as violations of God's will.","reviewStatus":"pending"},{"ref":"Genesis 6:12","explanation":"God's examination of the earth reveals widespread corruption in human ways, not merely isolated offenses.","context":"The verse intensifies the verdict of verse 11 and prepares for God's direct speech to Noah.","crossReferences":["Genesis 6:11","Psalm 14:2"],"application":"Measure conduct by God's standard rather than by what has become common.","reviewStatus":"pending"},{"ref":"Genesis 6:13","explanation":"God tells Noah that judgment is approaching because violence fills the earth; the warning is accompanied by instructions for preservation.","context":"The divine announcement follows the repeated description of corruption and introduces the ark command.","crossReferences":["Genesis 6:11","Genesis 6:14"],"application":"Listen when God's word exposes wrongdoing and provides a way to respond.","reviewStatus":"pending"},{"ref":"Genesis 6:14","explanation":"Noah is commanded to construct an ark with compartments and protective coating, showing that God's provision includes concrete instructions.","context":"The ark instructions begin immediately after the judgment announcement and continue through verse 16.","crossReferences":["Genesis 6:13","Hebrews 11:7"],"application":"Faith responds to God's word with practical obedience.","reviewStatus":"pending"},{"ref":"Genesis 6:15","explanation":"The ark's length, breadth and height are specified, emphasizing that Noah's task was to follow an actual design rather than invent his own.","context":"This verse is part of the detailed building instructions for the means of preservation.","crossReferences":["Genesis 6:14","Genesis 6:16"],"application":"Carry out entrusted responsibilities carefully rather than casually.","reviewStatus":"pending"},{"ref":"Genesis 6:16","explanation":"God specifies an opening, a side door and three levels, continuing the ordered design of the ark.","context":"The passage concerns the arrangement of the vessel; the precise construction details are not all explained by the text.","crossReferences":["Genesis 6:14","Genesis 6:15"],"application":"Attend to the details of responsibilities God has made clear.","reviewStatus":"pending"},{"ref":"Genesis 6:17","explanation":"God explicitly announces the flood as an act of judgment against life on the earth, underscoring the gravity of the crisis.","context":"The warning stands between the ark's design and God's covenant promise to Noah.","crossReferences":["Genesis 6:13","Genesis 7:21"],"application":"Treat God's warnings with seriousness and humility.","reviewStatus":"pending"},{"ref":"Genesis 6:18","explanation":"God promises to establish His covenant with Noah and specifies that his household will enter the ark.","context":"The covenant promise introduces hope within the announcement of judgment and anticipates its fuller expression after the flood.","crossReferences":["Genesis 9:9","Genesis 6:17"],"application":"Trust God's faithfulness and respond to His provision.","reviewStatus":"pending"},{"ref":"Genesis 6:19","explanation":"God instructs Noah to bring pairs of living creatures into the ark to preserve their lives through the flood.","context":"The preservation of animal life follows the promise concerning Noah's household and reflects care for creation.","crossReferences":["Genesis 6:18","Genesis 7:2"],"application":"Exercise responsible care for the living world entrusted to human stewardship.","reviewStatus":"pending"},{"ref":"Genesis 6:20","explanation":"Birds, livestock and creeping creatures are described according to their kinds, reinforcing the breadth of the preservation plan.","context":"The repetition elaborates verse 19 and connects with the language of living kinds in the creation account.","crossReferences":["Genesis 1:24","Genesis 6:19"],"application":"Recognize that faithful preparation includes care for needs beyond one's own.","reviewStatus":"pending"},{"ref":"Genesis 6:21","explanation":"Noah must gather food for his household and the animals, showing that preservation requires practical provision as well as shelter.","context":"The command completes the preparations before the narrative records Noah's response.","crossReferences":["Genesis 6:19","Genesis 6:22"],"application":"Combine trust in God with responsible preparation.","reviewStatus":"pending"},{"ref":"Genesis 6:22","explanation":"Noah does what God commands, closing the chapter with a concise testimony of obedient faith.","context":"The statement concludes the ark instructions and prepares for the further commands and flood narrative of Genesis 7.","crossReferences":["Genesis 7:5","Hebrews 11:7"],"application":"Let obedience be the practical expression of faith.","reviewStatus":"pending"},{"ref":"Genesis 7:1","explanation":"The LORD invites Noah and his household into the ark, identifying Noah as righteous amid his generation.","context":"This summons follows the ark's construction and moves the account from preparation to preservation.","crossReferences":["Genesis 6:9","Hebrews 11:7"],"application":"Respond to God's word with faith and responsible action.","reviewStatus":"pending"},{"ref":"Genesis 7:2","explanation":"Noah receives different instructions for clean and unclean animals, with greater numbers of the clean animals.","context":"The distinction becomes important when Noah later offers sacrifices after the flood; the text does not explain every detail of the classification here.","crossReferences":["Genesis 7:8","Genesis 8:20"],"application":"Pay attention to what Scripture actually commands rather than assuming every instruction is identical.","reviewStatus":"pending"},{"ref":"Genesis 7:3","explanation":"Birds are also included in the preservation instructions, with the stated purpose of maintaining life on the earth.","context":"The command extends God's concern for living creatures beyond Noah's immediate family.","crossReferences":["Genesis 6:20","Genesis 8:17"],"application":"Practice stewardship that considers future generations and the wider creation.","reviewStatus":"pending"},{"ref":"Genesis 7:4","explanation":"God specifies seven days before the rain and announces a forty-day period of judgment.","context":"The time warning gives Noah a definite interval before the flood begins, while the coming destruction is described plainly.","crossReferences":["Genesis 7:10","Genesis 7:12"],"application":"Treat warnings seriously and use available time wisely.","reviewStatus":"pending"},{"ref":"Genesis 7:5","explanation":"Noah obeys the LORD's instructions, repeating the testimony of obedience at the end of the preceding chapter.","context":"The brief statement links God's command in verses 1–4 to the actions that follow.","crossReferences":["Genesis 6:22","Genesis 7:1"],"application":"Let faithful conduct accompany professions of faith.","reviewStatus":"pending"},{"ref":"Genesis 7:6","explanation":"The narrative dates the flood to Noah's six-hundredth year, anchoring the event within the book's family chronology.","context":"The age notice precedes the entry into the ark and the more precise date in verse 11.","crossReferences":["Genesis 5:32","Genesis 7:11"],"application":"Remember that obedience is required throughout the stages of life.","reviewStatus":"pending"},{"ref":"Genesis 7:7","explanation":"Noah enters the ark with his wife, sons and daughters-in-law because of the approaching floodwaters.","context":"The household's entry fulfils the covenant-related promise given in Genesis 6:18.","crossReferences":["Genesis 6:18","1 Peter 3:20"],"application":"Value God's provision and act on His instructions.","reviewStatus":"pending"},{"ref":"Genesis 7:8","explanation":"Clean and unclean animals, birds and creeping creatures are named among those entering the ark.","context":"The verse begins a list completed in verse 9, showing the breadth of animal life included.","crossReferences":["Genesis 7:2","Genesis 7:9"],"application":"Recognize the importance of preserving the life God has made.","reviewStatus":"pending"},{"ref":"Genesis 7:9","explanation":"Animals enter in male-and-female pairs according to God's command to Noah.","context":"The verse completes the animal list and recalls the earlier preservation instructions.","crossReferences":["Genesis 6:19","Genesis 7:8"],"application":"Follow clear responsibilities carefully and consistently.","reviewStatus":"pending"},{"ref":"Genesis 7:10","explanation":"After the seven-day interval, the floodwaters arrive as God had announced.","context":"The narrative records the fulfilment of the warning given in verse 4.","crossReferences":["Genesis 7:4","Genesis 7:11"],"application":"Do not confuse delayed consequences with the absence of accountability.","reviewStatus":"pending"},{"ref":"Genesis 7:11","explanation":"The flood's beginning is precisely dated and described through waters from below and above.","context":"The verse combines a chronological notice with the opening of the deep and the heavens, depicting the overwhelming arrival of the flood.","crossReferences":["Genesis 7:6","Genesis 8:2"],"application":"Approach accounts of divine judgment with reverence rather than sensationalism.","reviewStatus":"pending"},{"ref":"Genesis 7:12","explanation":"Rain falls for forty days and nights, fulfilling the duration previously announced by God.","context":"The verse confirms the warning of verse 4 and precedes the account of the waters increasing.","crossReferences":["Genesis 7:4","Genesis 7:17"],"application":"Recognize the seriousness of God's word and promises.","reviewStatus":"pending"},{"ref":"Genesis 7:13","explanation":"The eight members of Noah's household are named as entering the ark on the appointed day.","context":"This verse supplies the family detail behind the earlier summary of entry in verse 7.","crossReferences":["Genesis 7:7","1 Peter 3:20"],"application":"Be attentive to the welfare of those entrusted to your care.","reviewStatus":"pending"},{"ref":"Genesis 7:14","explanation":"The ark receives land animals and birds according to their kinds, continuing the preservation of created life.","context":"The repeated phrase 'after his kind' recalls the categories used in the creation narrative.","crossReferences":["Genesis 1:24","Genesis 7:13"],"application":"Care for the created world without neglecting human responsibilities.","reviewStatus":"pending"},{"ref":"Genesis 7:15","explanation":"Living creatures enter the ark in pairs, preserving life through the coming flood.","context":"The account restates the entry of animals, emphasizing the fulfilment of God's instructions.","crossReferences":["Genesis 6:19","Genesis 7:9"],"application":"Value orderly preparation in fulfilling important duties.","reviewStatus":"pending"},{"ref":"Genesis 7:16","explanation":"Male and female creatures enter as commanded, and the LORD Himself shuts Noah in.","context":"The closing of the ark marks the completion of entry and the transition to the rising floodwaters.","crossReferences":["Genesis 7:15","Genesis 7:17"],"application":"Trust God's care while obeying what He has clearly required.","reviewStatus":"pending"},{"ref":"Genesis 7:17","explanation":"The floodwaters rise and lift the ark above the ground, so the means of preservation begins to float.","context":"This verse introduces the movement of the ark as the forty-day flood develops.","crossReferences":["Genesis 7:12","Genesis 7:18"],"application":"Remember that provision and protection may come amid difficult circumstances.","reviewStatus":"pending"},{"ref":"Genesis 7:18","explanation":"The waters increase greatly and the ark moves upon their surface.","context":"The description continues the rising-water sequence begun in verse 17.","crossReferences":["Genesis 7:17","Genesis 7:19"],"application":"Do not mistake surrounding turmoil for proof that God has abandoned His promises.","reviewStatus":"pending"},{"ref":"Genesis 7:19","explanation":"The floodwaters reach even the high hills described as being under the whole heaven.","context":"The narrative stresses the flood's extraordinary scope; interpretations of its geographic extent differ among readers.","crossReferences":["Genesis 7:18","Genesis 7:20"],"application":"Avoid overconfident claims beyond what an interpretation can securely establish.","reviewStatus":"pending"},{"ref":"Genesis 7:20","explanation":"The waters rise fifteen cubits and cover the mountains, adding a numerical detail to the preceding description.","context":"The measurement is presented as part of the account of the waters' height.","crossReferences":["Genesis 7:19","Genesis 8:4"],"application":"Read biblical numerical details attentively and without embellishment.","reviewStatus":"pending"},{"ref":"Genesis 7:21","explanation":"The flood brings death to moving land creatures and human beings outside the ark.","context":"The verse lists the categories affected, emphasizing the gravity of judgment rather than inviting graphic speculation.","crossReferences":["Genesis 7:23","Genesis 6:17"],"application":"Take the moral consequences of wrongdoing seriously.","reviewStatus":"pending"},{"ref":"Genesis 7:22","explanation":"The text specifies that land creatures possessing the breath of life die in the flood.","context":"This verse elaborates the preceding list by describing those on dry land.","crossReferences":["Genesis 7:21","Genesis 2:7"],"application":"Recognize the dependence of creaturely life upon God.","reviewStatus":"pending"},{"ref":"Genesis 7:23","explanation":"The narrative summarizes the destruction on the ground and the preservation of Noah and those with him in the ark.","context":"The summary contrasts the widespread loss of life with the household and animals kept within the ark.","crossReferences":["Genesis 7:16","Hebrews 11:7"],"application":"Receive God's mercy with gratitude and humility.","reviewStatus":"pending"},{"ref":"Genesis 7:24","explanation":"The waters prevail for one hundred and fifty days, extending the flood chronology beyond the forty days of rainfall.","context":"The verse closes the chapter and leads into the account of God's remembrance of Noah in Genesis 8.","crossReferences":["Genesis 8:3","Genesis 7:12"],"application":"Persevere patiently when a difficult season lasts longer than expected.","reviewStatus":"pending"},{"ref":"Genesis 8:1","explanation":"God remembers Noah and the living creatures in the ark and sends a wind that begins to reduce the waters.","context":"After the flood's prolonged rise, the narrative turns to God's continuing care and the beginning of restoration.","crossReferences":["Genesis 7:24","Genesis 9:15"],"application":"Trust that God's care is not absent during long periods of waiting.","reviewStatus":"pending"},{"ref":"Genesis 8:2","explanation":"The sources of the floodwaters are restrained and the rain stops.","context":"The verse describes the reversal of the waters' arrival in Genesis 7:11.","crossReferences":["Genesis 7:11","Genesis 8:3"],"application":"Give thanks when difficult circumstances begin to change.","reviewStatus":"pending"},{"ref":"Genesis 8:3","explanation":"The waters recede steadily, with the one-hundred-and-fifty-day period marking the flood chronology.","context":"The statement continues the decline of the waters and prepares for the ark's resting place.","crossReferences":["Genesis 7:24","Genesis 8:4"],"application":"Practice patience while restoration unfolds gradually.","reviewStatus":"pending"},{"ref":"Genesis 8:4","explanation":"The ark comes to rest on the mountains of Ararat on a specified date.","context":"The text identifies a mountainous region but does not establish a precise modern landing site.","crossReferences":["Genesis 7:17","Genesis 8:5"],"application":"Avoid turning uncertain geographic details into claims of biblical certainty.","reviewStatus":"pending"},{"ref":"Genesis 8:5","explanation":"The mountain tops become visible as the waters continue to decrease.","context":"The dated observation shows that the waters receded in stages rather than disappearing instantly.","crossReferences":["Genesis 8:3","Genesis 8:13"],"application":"Recognize that progress may be real even before the whole task is finished.","reviewStatus":"pending"},{"ref":"Genesis 8:6","explanation":"After forty days, Noah opens the window he had made in the ark.","context":"The action introduces the sequence of birds sent out to observe conditions outside.","crossReferences":["Genesis 6:16","Genesis 8:7"],"application":"Use careful observation alongside patient trust.","reviewStatus":"pending"},{"ref":"Genesis 8:7","explanation":"Noah releases a raven, which moves about while the land continues drying.","context":"The raven is the first bird sent out in the account, before the dove's repeated journeys.","crossReferences":["Genesis 8:6","Genesis 8:8"],"application":"Gather information responsibly before making major decisions.","reviewStatus":"pending"},{"ref":"Genesis 8:8","explanation":"Noah sends a dove to test whether the ground is becoming accessible.","context":"The dove's journey begins a series of observations about the receding waters.","crossReferences":["Genesis 8:7","Genesis 8:9"],"application":"Seek reliable evidence rather than acting on assumptions.","reviewStatus":"pending"},{"ref":"Genesis 8:9","explanation":"The dove returns because it finds no resting place, and Noah brings it safely back into the ark.","context":"The bird's return indicates that the land is not yet suitable for departure.","crossReferences":["Genesis 8:8","Genesis 8:10"],"application":"Show care for vulnerable creatures and be willing to wait.","reviewStatus":"pending"},{"ref":"Genesis 8:10","explanation":"Noah waits seven more days before sending the dove again.","context":"The repeated interval highlights measured patience in assessing changing conditions.","crossReferences":["Genesis 8:9","Genesis 8:11"],"application":"Resist the pressure to act before the proper time.","reviewStatus":"pending"},{"ref":"Genesis 8:11","explanation":"The dove returns with a fresh olive leaf, giving Noah evidence that the waters have receded.","context":"The sign is observational: vegetation has become accessible, though the narrative has not yet authorized leaving the ark.","crossReferences":["Genesis 8:10","Genesis 8:12"],"application":"Welcome encouraging signs without assuming every process is complete.","reviewStatus":"pending"},{"ref":"Genesis 8:12","explanation":"After another seven days, Noah sends the dove again, and it does not return.","context":"The final flight follows the earlier unsuccessful journey and the olive-leaf report.","crossReferences":["Genesis 8:11","Genesis 8:13"],"application":"Let repeated observation guide patient decisions.","reviewStatus":"pending"},{"ref":"Genesis 8:13","explanation":"Noah sees that the surface of the ground is dry after removing the ark's covering.","context":"The dated report precedes a later statement that the earth was fully dry and God's instruction to leave.","crossReferences":["Genesis 8:14","Genesis 8:16"],"application":"Distinguish visible improvement from full readiness.","reviewStatus":"pending"},{"ref":"Genesis 8:14","explanation":"The earth is reported dry on a later date, completing the sequence of receding waters.","context":"The verse supplies a second chronological marker after Noah's earlier observation.","crossReferences":["Genesis 8:13","Genesis 8:15"],"application":"Be attentive to the difference between early progress and completed preparation.","reviewStatus":"pending"},{"ref":"Genesis 8:15","explanation":"God speaks to Noah after the earth has dried, preparing him for the next stage.","context":"This short transition introduces the explicit command to leave the ark.","crossReferences":["Genesis 8:14","Genesis 8:16"],"application":"Seek to respond to God's direction rather than relying only on circumstances.","reviewStatus":"pending"},{"ref":"Genesis 8:16","explanation":"God commands Noah and his household to leave the ark.","context":"The command follows the long waiting period and the restoration of dry land.","crossReferences":["Genesis 7:1","Genesis 8:18"],"application":"Recognize that faith includes moving forward when the time comes.","reviewStatus":"pending"},{"ref":"Genesis 8:17","explanation":"God commands the release of the animals so they may multiply upon the earth.","context":"The words echo the blessing of fruitfulness given in the creation account.","crossReferences":["Genesis 1:22","Genesis 9:1"],"application":"Exercise stewardship with concern for the flourishing of life.","reviewStatus":"pending"},{"ref":"Genesis 8:18","explanation":"Noah and his family leave the ark in response to God's command.","context":"The family's departure fulfils the direction in verse 16 and signals a new beginning.","crossReferences":["Genesis 8:16","Genesis 8:19"],"application":"Express faith through obedience when circumstances change.","reviewStatus":"pending"},{"ref":"Genesis 8:19","explanation":"The animals leave the ark according to their kinds, returning to life on the earth.","context":"The list completes the account of departure and reflects the preservation described earlier.","crossReferences":["Genesis 7:14","Genesis 8:17"],"application":"Remember responsibilities toward the created world.","reviewStatus":"pending"},{"ref":"Genesis 8:20","explanation":"Noah builds an altar and offers burnt offerings from clean animals and birds to the LORD.","context":"This is Noah's first recorded act after leaving the ark, and it follows the earlier provision of clean animals.","crossReferences":["Genesis 7:2","Hebrews 11:7"],"application":"Respond to deliverance with grateful worship.","reviewStatus":"pending"},{"ref":"Genesis 8:21","explanation":"The LORD receives the offering and declares that He will not again strike every living thing in the same manner, despite the persistence of human sinfulness.","context":"The verse presents divine mercy without denying the continuing reality of sin; the covenant is developed further in Genesis 9.","crossReferences":["Genesis 6:5","Genesis 9:11"],"application":"Do not mistake God's mercy for approval of sin.","reviewStatus":"pending"},{"ref":"Genesis 8:22","explanation":"God promises the continuing rhythms of planting, harvest, seasons and day and night while the earth remains.","context":"The promise concludes the flood account with assurance of an ordered world in which life can continue.","crossReferences":["Genesis 1:14","Jeremiah 33:25"],"application":"Give thanks for God's sustaining faithfulness in ordinary life.","reviewStatus":"pending"}];
const notes=Object.fromEntries(entries.filter(e=>e.reviewStatus==='pending').map(e=>[e.ref,{explanation:e.explanation,context:e.context,references:e.crossReferences.join('; '),application:e.application,reviewStatus:e.reviewStatus}]));
if(typeof window.registerConcordanceStudyNotes==='function')window.registerConcordanceStudyNotes(notes);
})();
